    id: `deck:${deck.id}`,
    targetId: deck.id,
    targetType: "deck",
    ...laneFor(priorities, "deck", deck.id, deck.topic, due.length > 0 ? "focus" : "maintain"),
    title: deck.title,
    topic: deck.topic,
    description: "Spaced-repetition deck",
    dueCount: due.length,
    overdueCount: overdue.length,
    nextDueAt: futureDueAt,
